package com.nstut.biotech.jei;

import com.nstut.biotech.Biotech;import com.nstut.biotech.machines.MachineRegistries;import com.nstut.biotech.recipes.SlaughterhouseRecipe;import com.nstut.nstutlib.recipes.OutputItem;import mezz.jei.api.constants.VanillaTypes;import mezz.jei.api.gui.builder.IRecipeLayoutBuilder;import mezz.jei.api.gui.drawable.IDrawable;import mezz.jei.api.gui.ingredient.IRecipeSlotsView;import mezz.jei.api.helpers.IGuiHelper;import mezz.jei.api.recipe.IFocusGroup;import mezz.jei.api.recipe.RecipeIngredientRole;import mezz.jei.api.recipe.RecipeType;import mezz.jei.api.recipe.category.IRecipeCategory;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.network.chat.Component;import net.minecraft.resources.Identifier;import net.minecraft.world.item.ItemStack;import net.minecraft.world.item.crafting.Ingredient;import net.neoforged.neoforge.fluids.FluidStack;import org.jetbrains.annotations.NotNull;import java.util.List;
public class SlaughterhouseCategory implements IRecipeCategory<SlaughterhouseRecipe>{public static final Identifier UID=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,MachineRegistries.SLAUGHTERHOUSE.id());public static final Identifier TEXTURE=Identifier.fromNamespaceAndPath(Biotech.MOD_ID,"textures/gui/jei/"+MachineRegistries.SLAUGHTERHOUSE.id()+".png");public static final RecipeType<SlaughterhouseRecipe> TYPE=new RecipeType<>(UID,SlaughterhouseRecipe.class);private final IDrawable background,icon;public SlaughterhouseCategory(IGuiHelper h){background=h.createDrawable(TEXTURE,0,0,136,70);icon=h.createDrawableIngredient(VanillaTypes.ITEM_STACK,new ItemStack(MachineRegistries.SLAUGHTERHOUSE.blockItem().get()));}@Override public @NotNull RecipeType<SlaughterhouseRecipe> getRecipeType(){return TYPE;}@Override public @NotNull Component getTitle(){return Component.translatable("block.biotech."+MachineRegistries.SLAUGHTERHOUSE.id());}@Override public int getWidth(){return background.getWidth();}@Override public int getHeight(){return background.getHeight();}@Override public @NotNull IDrawable getIcon(){return icon;}@Override public void setRecipe(@NotNull IRecipeLayoutBuilder b,@NotNull SlaughterhouseRecipe r,@NotNull IFocusGroup f){Ingredient i=Ingredient.of(r.getItemIngredients().get(0).getItemStack().getItem());FluidStack fl=r.getFluidIngredients().get(0);List<Ingredient> o=r.getItemOutputs().stream().map(v->Ingredient.of(v.getItemStack().getItem())).toList();b.addSlot(RecipeIngredientRole.INPUT,23,4).addIngredients(i);b.addSlot(RecipeIngredientRole.INPUT,23,24).addFluidStack(fl.getFluid(),fl.getAmount()).setFluidRenderer(fl.getAmount(),false,16,16);for(int n=0;n<o.size();n++)b.addSlot(RecipeIngredientRole.OUTPUT,79+(n%3)*20,1+(n/3)*28).addIngredients(o.get(n));}@Override public void draw(SlaughterhouseRecipe r,@NotNull IRecipeSlotsView s,GuiGraphicsExtractor g,double x,double y){background.draw(g);Minecraft m=Minecraft.getInstance();g.text(m.font,"Energy: "+r.getTotalEnergy()+" FE",0,60,4210752,false);List<OutputItem> o=r.getItemOutputs();for(int n=0;n<o.size();n++){String chance=o.get(n).getChance()<1?(int)(o.get(n).getChance()*100)+"%":"";g.text(m.font,chance,79+(n%3)*20,20+(n/3)*28,4210752,false);}}}
